-- Rifts World Book 33: Northern Gun One, five vehicles (printed 85-86, 95-98): Police Interceptor Rocket Bike NG-RB-122, NG 122-EXO Light Police Power Armor, Hovertrain Locomotive NG-HCH-1228, Hovertrain Boxcar/Flatbed/Passenger Cars NG-HCB-1B, Hovertrain Weapon Car NG-HCB-AD2
-- 5 vehicle rows, with 36 locations and 16 weapon entries.
--
-- One-off data script, run once per environment. NOT a migration - it adds
-- rows, not schema.
--
--   node scripts/d1-apply.mjs --local apps/character-creator/db/~292-northern-gun-1-vehicles-police-hovertrain.sql
--
-- Written by scripts/vessel-sql.mjs from 1 worker file(s). Every value
-- is printable ASCII, every row cites its book, and a Main Body location
-- agrees with its vehicle's mdc_main_body.

INSERT OR IGNORE INTO vehicles (slug, name, system, vehicle_class, crew, passengers, speed_ground, speed_air, speed_water, dimensions, weight_tons, mdc_main_body, is_mega_damage, ar, cost, cost_note, description, source_book) VALUES
  ('ng-rb-122-police-interceptor', 'Police NG Interceptor Rocket Bike', 'rifts', 'vehicle', 'One pilot', 'None', '200 mph (320 km) maximum on land; past that it lifts off on its own to at least 50 ft (15.2 m) and flies', '300 mph (480 km) maximum; cruises at 45-90 mph (72-144 km). VTOL, can hover in place. Ceiling 1,600 ft (488 m) over land or water. Eight hours of continuous flight before the engine must be shut down to cool; each further 10 minutes carries a cumulative 20% chance the engine quits and the bike crashes', 'Flies over water at full speed; cannot ride on the surface or go under it, and sinks if it comes down', 'Height 5 ft 9 in (1.8 m); width 5 ft (1.5 m); length 12 ft (3.6 m)', '0.65', 122, 1, NULL, 650000, 'Nuclear 1.2 million credits, Solid Oxide 850,000, electric battery 650,000; the lowest is stored. Issued only to the Ishpeming Police Department: not sold on the open market, not even to other kingdoms'' police.', 'Model Type: NG-RB-122. Class: Rocket Cycle, Police Interceptor. A prototype rocket bike Northern Gun built for the Ishpeming police, borrowing its idea from Coalition rocket cycles. It patrols the IM Highway, back roads and city streets and runs down suspects in slower vehicles, and few land vehicles or power armor suits can outpace it. Its nose carries a paired laser, one barrel for mega-damage and one for S.D.C. warning or subduing shots, and two side launchers carry mini-missiles for armored targets and monsters. Weight 1,300 lbs (585 kg). Cargo: a small side compartment between seat and tail fits a first aid kit, a canteen, three spare pistol E-Clips, two flares, a walkie-talkie and a lunch. Power: nuclear, 12 year life; Solid Oxide and battery versions exist. Special systems: flashing red and blue lights and a siren in the nose, running lights around the nose and launchers, and a loudspeaker and short- and long-range radio, both tied to the rider''s helmet. Painted in IPD matte gray with blue, red and black trim and the NG logo, the scheme the police power armor also wears.', 'Rifts World Book 33: Northern Gun One p.85-86'),
  ('ng-122-exo-police-power-armor', 'NG 122-EXO Light Police Power Armor', 'rifts', 'power-armor', 'One wearer', 'None', 'Not printed; the exoskeleton adds +8 to the wearer''s Spd', 'None printed', 'Not printed', 'Not printed; worn like bulky body armor', '0.025', 120, 1, NULL, NULL, 'Not sold: exclusive to the Ishpeming/NG police. On the retail market it would likely fetch 100,000-150,000 credits.', 'Model Type: NG 122-EXO. The suit Ishpeming police officers wear, reverse-engineered from the Triax T-11 Enhanced Body Armor; whether it is heavy body armor with an exoskeleton or a light power armor is argued either way. It is bulky and armors the torso most heavily. Weight 50 lbs (22.5 kg; the book misprints km). Fair mobility: -12% to Acrobatics, Gymnastics, Prowl and Swimming, no penalty to Climbing or Running. The exoskeleton gives the wearer +6 P.S., +8 Spd, +6 ft (1.8 m) to leap height and length, and halves the rate of fatigue. Matte gray with blue, red and black trim and the NG logo, matching the police rocket bikes. No built-in weapons are printed.', 'Rifts World Book 33: Northern Gun One p.86'),
  ('ng-hch-1228-hovertrain-locomotive', 'Hovertrain Locomotive', 'rifts', 'vehicle', 'Three: a driver, an engineer, and a gunner who doubles as backup driver', 'None printed; the cargo area has two fold-down cots for the crew', '250 mph (400 km) running alone; 125 mph (200 km) pulling more than three cars or fully loaded; 60 mph (96 km) overloaded (up to 40% past rated weight) or hauling dangerous cargo. Hovers at up to 20 ft (6.1 m) even at full capacity, 12 ft (3.6 m) overloaded', 'None', 'Crosses ponds, marsh and streams no deeper than 20 ft (6.1 m); cannot ride on open water and sinks in deep water', 'Height 39 ft (11.8 m); width 44 ft (13.4 m); length 68 ft (20.7 m)', '98', 950, 1, NULL, 97000000, '97 million credits. Nuclear only.', 'Model Type: NG-HCH-1228. Class: Hover Locomotive. The engine of a Northern Gun hovertrain, a string of hover platforms each lifting itself but all drawn forward by this one machine, which can haul hundreds of thousands of tons over rough ground, shallow water and debris that would stop a truck. Designed by Gregory John Clark, Nicky Warren, David Chittim and Ross Simmerman. Only a nuclear core gives it enough power; gasoline, diesel and Solid Oxide cells all fall short. Four huge hover fans lift it, and their downdraft is a hazard: anyone up to 11 ft (3.3 m) tall within 35 ft (10.7 m) has a 01-90% chance (01-50% for larger beings) of being knocked down and thrown 1D4x10 ft (3-12.2 m), taking 1D6 M.D., losing initiative and two melee attacks. Hovertrains reach inland from shore landings such as Toledo and Benton Harbor, run scheduled passenger routes along the IM Highway, and serve lumber and mining camps; any leaving the Republic carries weapon cars or a robot escort. Cargo: a small area with a toilet, sink, two fold-down cots and room for some equipment, luggage, or one motorcycle or small power armor. Power: nuclear, 15 year life. Sensors as the standard robot features.', 'Rifts World Book 33: Northern Gun One p.95-96'),
  ('ng-hcb-1b-hovertrain-boxcar', 'Hovertrain Boxcar/Flatbed/Passenger Cars', 'rifts', 'vehicle', 'None', 'Passenger car: over a hundred, depending on how the seating is laid out; boxcar and flatbed: none', 'Towed by the locomotive. Detached, it can hover and be pushed or pulled at 10 mph (16 km) by one giant robot of Robot P.S. 32 or more or by a heavy construction vehicle, tank or APC; half that overloaded or with dangerous cargo. Hovers at up to 20 ft (6.1 m)', 'None', 'None', 'Height 28 ft (8.5 m); width 36 ft (11 m); length 80 ft (24.4 m)', '10 empty; up to 210 fully loaded', 300, 1, NULL, 4000000, '4 million credits; the passenger car version 4.5 million.', 'Model Type: NG-HCB-1B-Standard. Class: Hover-Capable Boxcar. Lead designers David Marble and Maffy. One standard hovertrain car in three forms. A boxcar holds about what three to five pre-Rifts semi-trailers did, enough for full-size combat robots, tanks, light aircraft or heaps of ore or grain. A flatbed carries the biggest loads, robots, tanks, planes, farm harvesters, and parts for ships, wind turbines and power plants, all lashed down against a sudden loss of hover power. A passenger car seats more than a hundred, and some fit in a dining area, bar and toilet. Cargo: 200 tons per car, 40 more overloaded. Power: nuclear, 15 year life. No weapons and no sensors.', 'Rifts World Book 33: Northern Gun One p.96-97'),
  ('ng-hcb-ad2-hovertrain-weapon-car', 'Hovertrain Weapon Car', 'rifts', 'vehicle', 'One communications officer and one gunner per weapon system, typically 2-6 turrets per car', 'Up to 20 security personnel, 10 of them in power armor', 'Towed by the locomotive. Detached, it can hover and be pushed or pulled at 10 mph (16 km) by one giant robot of P.S. 32 or more or by a heavy construction vehicle, tank or APC. Hovers at up to 20 ft (6.1 m)', 'None', 'None', 'Height 28 ft (8.5 m); width 36 ft (11 m); length 80 ft (24.4 m)', '30-40', 450, 1, NULL, 15000000, '15-22 million credits depending on how many weapon systems it carries and which; the low end is stored. Each turret entry below prints its own cost.', 'Model Type: NG-HCB-AD2. Class: Weapon Bunker Boxcar. Also called a Defense Car. Lead designers Wayne Maynard, Frank Uhrmann and William McGoldrick. A hover boxcar given extra armor and turrets, coupled into a hovertrain as a moving bunker, and usually carrying a squad or two of troops to answer attacks and clear boarders. Some run with their guns in plain view, to draw fire onto the best-armored car, give away the attackers'' positions and deter bandits outright; others are disguised as ordinary boxcars, turrets hidden inside or under tarps until the last moment, with guards and often flying power armor or jet-pack mercs spread through the train. Giant robots riding open flatbeds are beginning to replace these cars, since a robot can step off and fight. Weight is printed twice, 30-40 tons fully loaded and around 40 tons. Cargo: a locking gun rack, 20 fold-down seats and a dozen lockers. Power: nuclear, 15 year life. Sensors as the standard robot features. Weapons: a car carries three heavy systems, six medium or nine light, most often mixed: (A) one heavy, two medium and 2-3 light; (B) two heavy and two medium; (C) two heavy, one medium and 2-3 light; (D) four medium and 2-3 light. Every weapon is a cannon in a turret rotating 180 degrees with a 45 degree arc; the weapon list below is the menu a buyer picks from, not one car''s fit. A troop complement of 10 per squad is an option, priced by troop type.', 'Rifts World Book 33: Northern Gun One p.97-98');

INSERT OR IGNORE INTO vehicle_locations (vehicle_slug, location, mdc, mdc_note, ordinal) VALUES
  ('ng-rb-122-police-interceptor', 'Heavy M.D. Laser (1, nose)', 20, 'Small target: Called Shot, -4 to strike.', 1),
  ('ng-rb-122-police-interceptor', 'Light S.D.C. Laser (1, nose)', 10, 'Small target: Called Shot, -4 to strike.', 2),
  ('ng-rb-122-police-interceptor', 'Mini-Missile/Mini-Torpedo Tubes (2, side)', 25, 'Each. Small target: Called Shot, -4 to strike.', 3),
  ('ng-rb-122-police-interceptor', 'Reinforced Windshield (1, front)', 15, NULL, 4),
  ('ng-rb-122-police-interceptor', 'Nose Police Lights & Headlights (2, nose)', 4, 'Each. Small target: Called Shot, -4 to strike.', 5),
  ('ng-rb-122-police-interceptor', 'Directional Jets (8, concealed)', 10, 'Each. Losing four or more gives -15% to the piloting skill; losing 6-8, -25%.', 6),
  ('ng-rb-122-police-interceptor', 'Rocket Jet (1, rear)', 50, 'Destroyed, the bike can only hover and creep at 3 mph (4.8 km).', 7),
  ('ng-rb-122-police-interceptor', 'Tail Fin (1, rear)', 45, 'Small target: Called Shot, -4 to strike.', 8),
  ('ng-rb-122-police-interceptor', 'Main Body', 122, 'Reduced to zero, the vehicle shuts down and is useless.', 9),
  ('ng-122-exo-police-power-armor', 'Helmet', 50, NULL, 1),
  ('ng-122-exo-police-power-armor', 'Arms (2)', 25, 'Each.', 2),
  ('ng-122-exo-police-power-armor', 'Legs (2)', 50, 'Each.', 3),
  ('ng-122-exo-police-power-armor', 'Main Body', 120, NULL, 4),
  ('ng-hch-1228-hovertrain-locomotive', 'Radar/Sensor Array (1, large)', 100, 'Small target: Called Shot, -4 to strike.', 1),
  ('ng-hch-1228-hovertrain-locomotive', 'Communications Array (1, small)', 50, 'Small target: Called Shot, -4 to strike.', 2),
  ('ng-hch-1228-hovertrain-locomotive', 'Headlights (2)', 10, 'Each. Small target: Called Shot, -4 to strike.', 3),
  ('ng-hch-1228-hovertrain-locomotive', 'Front Hover Fans (2, side)', 450, 'Each. Printed without the fan footnote''s double asterisk, though the footnote speaks of the hover fans generally.', 4),
  ('ng-hch-1228-hovertrain-locomotive', 'Rear Hover Fans (2, side)', 350, 'Each. Losing one fan cuts speed by 30%; losing two or more cuts speed and altitude by 90% and gives -50% to piloting, and the train should stop and wait for recovery or field repair.', 5),
  ('ng-hch-1228-hovertrain-locomotive', 'Observation Decks (2, one each side)', 100, 'Each.', 6),
  ('ng-hch-1228-hovertrain-locomotive', 'Forward Weapon Turret (1)', 100, NULL, 7),
  ('ng-hch-1228-hovertrain-locomotive', 'Reinforced Crew Compartment', 120, NULL, 8),
  ('ng-hch-1228-hovertrain-locomotive', 'Main Body', 950, 'Reduced to zero, the vehicle shuts down and is useless.', 9),
  ('ng-hcb-1b-hovertrain-boxcar', 'Sliding Side Door (boxcar only)', 50, NULL, 1),
  ('ng-hcb-1b-hovertrain-boxcar', 'Windows (40, 20 each side; passenger cars only)', 5, 'Each. Small target: Called Shot, -4 to strike, doubled at 100 mph (160 km) or faster.', 2),
  ('ng-hcb-1b-hovertrain-boxcar', 'Hover Fans (4, two each side)', 180, 'Each. Losing one or two slows the locomotive 5%; three or four, 10% and -2% to piloting. Losses add up across cars, and a car that cannot hover may be left behind.', 3),
  ('ng-hcb-1b-hovertrain-boxcar', 'Main Body', 300, 'Reduced to zero, the hover fans fail and the cargo or passengers spill out, taking 2D6 M.D. from the fall.', 4),
  ('ng-hcb-ad2-hovertrain-weapon-car', 'Sensor Array (1)', 35, 'Small target: Called Shot, -4 to strike, doubled at 100 mph (160 km) or faster.', 1),
  ('ng-hcb-ad2-hovertrain-weapon-car', 'Top Hatches (2)', 50, 'Each. Small target: Called Shot, -4 to strike, doubled at 100 mph (160 km) or faster.', 2),
  ('ng-hcb-ad2-hovertrain-weapon-car', 'Side Hatches (4)', 100, 'Each. Small target: Called Shot, -4 to strike, doubled at 100 mph (160 km) or faster.', 3),
  ('ng-hcb-ad2-hovertrain-weapon-car', 'Window Slits (8, four each side)', 10, 'Each. Small target: Called Shot, -4 to strike, doubled at 100 mph (160 km) or faster.', 4),
  ('ng-hcb-ad2-hovertrain-weapon-car', 'Light Weapon Turret', 100, 'Per turret fitted.', 5),
  ('ng-hcb-ad2-hovertrain-weapon-car', 'Medium Weapon Turret', 150, 'Per turret fitted.', 6),
  ('ng-hcb-ad2-hovertrain-weapon-car', 'Heavy, Large Weapon Turret', 220, 'Per turret fitted. The Turret Note under Weapon Systems prints 200 for a heavy turret; the location table''s 220 is kept.', 7),
  ('ng-hcb-ad2-hovertrain-weapon-car', 'Mini-Missile Launcher/Turret', 120, 'Per turret fitted.', 8),
  ('ng-hcb-ad2-hovertrain-weapon-car', 'Hover Fans (4, two each side)', 180, 'Each. Losing one or two slows the locomotive 5%; three or four, 10% and -2% to piloting.', 9),
  ('ng-hcb-ad2-hovertrain-weapon-car', 'Main Body', 450, 'Reduced to zero, the hover fans, weapons and sensors all fail, and cargo or troops spill out, taking 2D6 M.D. from the fall.', 10);

INSERT OR IGNORE INTO vehicle_weapons (vehicle_slug, ordinal, name, damage, is_mega_damage, range, rate_of_fire, payload, bonus, note) VALUES
  ('ng-rb-122-police-interceptor', 1, 'Dual Nose Laser', '3D6 M.D. (heavy laser) or 4D6 S.D.C./Hit Point damage (light laser)', 1, '1,500 ft (457.2 m), either barrel', 'Each blast counts as one melee attack', 'Effectively unlimited', NULL, 'Fixed forward. The pilot switches between barrels; the S.D.C. laser can also be set to no damage and used for targeting and range-finding. Primary purpose anti-personnel; secondary assault and defense.'),
  ('ng-rb-122-police-interceptor', 2, 'Side Mounted Mini-Missile Launchers (2)', 'Varies by mini-missile or mini-torpedo type: high explosive 5D6 M.D. to a 5 ft (1.5 m) radius; armor piercing 1D4x10 M.D. to a 3 ft (0.9 m) radius; smoke and tear gas do no damage', 1, 'About one mile (1.6 km); tear gas half a mile', 'One at a time or in volleys of two or four', '16 mini-missiles or mini-torpedoes, 4 per launcher as printed', NULL, 'A turret on each side, 360 degree rotation with an up and down arc. Standard IPD load: 2 smoke (40 ft/12.2 m radius cloud), 4 riot tear gas (30 ft/9.1 m cloud; without eye cover and gas mask, -3 initiative and -5 to strike, parry and dodge for 1D4+4 melee rounds, half that in strong wind; sealed armor and vehicles are immune), 6 high explosive and 4 armor piercing. The printed 4 per launcher across two launchers does not make 16; the 16 and the 2-4-6-4 mix agree, and are kept. Torpedoes replace missiles for dock and lakeside work. Police never load plasma or fragmentation missiles, for the collateral damage. Purpose printed as anti-ship, secondarily anti-sea monster.'),
  ('ng-hch-1228-hovertrain-locomotive', 1, 'Forward-Mounted Laser Turret (1)', '4D6 M.D. per single blast', 1, '2,000 ft (610 m)', 'Each blast counts as one melee attack', 'Effectively unlimited', '+1 to strike via laser targeting, for a dedicated gunner only; none when the driver fires it', 'Turns 120 degrees side to side with a 25 degree up and down arc. Meant for defense and for scaring off large animals.'),
  ('ng-hcb-ad2-hovertrain-weapon-car', 1, 'Light Laser Cannon Turret', '3D6 M.D. per blast', 1, '2,000 ft (610 m)', 'Each blast counts as one attack', 'Effectively unlimited', NULL, 'Light weapon system, yet likely the car''s main long-range gun. Defense, anti-armor. Cost 2 million credits.'),
  ('ng-hcb-ad2-hovertrain-weapon-car', 2, 'Medium Laser Cannon Turret', '5D6 M.D. per blast', 1, '3,000 ft (914 m)', 'Each blast counts as one attack/action', 'Effectively unlimited', NULL, 'Defense, anti-armor. Cost 8 million credits.'),
  ('ng-hcb-ad2-hovertrain-weapon-car', 3, 'Heavy Laser Cannon Turret', '1D4x10 M.D. per blast', 1, '4,000 ft (1,219 m)', 'Each blast counts as one attack/action', 'Effectively unlimited', NULL, 'Defense, anti-armor. Cost 15 million credits.'),
  ('ng-hcb-ad2-hovertrain-weapon-car', 4, 'Mini-Missile Launcher Turret', 'Varies with missile type; plasma (1D6x10 M.D.) and armor piercing (1D4x10 M.D.) are standard', 1, 'One mile (1.6 km)', 'One at a time or in volleys of two, four or six', '48 missiles', NULL, 'Medium weapon system. Anti-armor, anti-personnel. Cost 2 million credits with one load of missiles.'),
  ('ng-hcb-ad2-hovertrain-weapon-car', 5, 'Light Ion Cannon Turret', '4D6 M.D. per blast', 1, '1,500 ft (457 m)', 'Each blast counts as one attack', 'Effectively unlimited', NULL, 'Defense, anti-armor. Cost 6 million credits.'),
  ('ng-hcb-ad2-hovertrain-weapon-car', 6, 'Medium Ion Cannon Turret', '6D6 M.D. per blast', 1, '1,800 ft (548.6 m)', 'Each blast counts as one attack', 'Effectively unlimited', NULL, 'Defense, anti-armor. Cost 8 million credits.'),
  ('ng-hcb-ad2-hovertrain-weapon-car', 7, 'Heavy Ion Cannon Turret', '1D4x10+6 M.D. per blast', 1, '2,000 ft (610 m)', 'Each blast counts as one attack', 'Effectively unlimited', NULL, 'Defense, anti-armor. Cost 12 million credits.'),
  ('ng-hcb-ad2-hovertrain-weapon-car', 8, 'Medium Plasma Cannon Turret', '6D6 M.D. per blast', 1, '2,000 ft (610 m)', 'Each blast counts as one attack', 'Effectively unlimited', NULL, 'Counts as a heavy weapon system. Defense, anti-armor. Cost 14 million credits.'),
  ('ng-hcb-ad2-hovertrain-weapon-car', 9, 'Heavy Plasma Cannon Turret', '1D6x10 M.D. per blast', 1, '2,000 ft (610 m)', 'Each blast counts as one attack', 'Effectively unlimited', NULL, 'Defense, anti-armor. Cost 22 million credits.'),
  ('ng-hcb-ad2-hovertrain-weapon-car', 10, 'Rail Gun Turret', '1D4x10 M.D. per 40 round burst', 1, '4,000 ft (1,219 m)', 'Each burst counts as one melee attack', '6,000 rounds, 150 bursts', NULL, 'Heavy weapon system: long reach, limited ammunition. Assault and anti-armor; anti-aircraft and defense. Cost 1.4 million credits, plus about two credits a round.'),
  ('ng-hcb-ad2-hovertrain-weapon-car', 11, 'Medium Particle Beam Turret', '1D4x10+8 M.D.', 1, '1,600 ft (488 m)', 'Each blast counts as one melee attack', 'Effectively unlimited', NULL, 'Heavy weapon system with a short reach. Defense, anti-armor. Cost 20 million credits.'),
  ('ng-hcb-ad2-hovertrain-weapon-car', 12, 'Heavy Particle Beam Turret', '1D6x10+10 M.D. per blast', 1, '2,000 ft (610 m)', 'Each blast counts as one melee attack', 'Effectively unlimited', NULL, 'Defense, anti-armor. Cost 35 million credits.'),
  ('ng-hcb-ad2-hovertrain-weapon-car', 13, 'Short-Range Missile Launchers', 'Varies with missile type; standard is armor piercing (2D6x10 M.D. to a 5 ft/1.5 m radius) or plasma (2D6x10 M.D. to a 15 ft/4.6 m radius)', 1, 'Five miles (8 km)', 'One at a time or in volleys of two, three or four per launcher', '6 total', NULL, 'Heavy weapon system. Assault; anti-missile and defense. Cost 6.5 million credits with one load of missiles.');

-- Read the result back. This script asserts its OWN rows and nothing else.
SELECT 'all 5 machines are in' AS assertion, count(*) AS got, 5 AS want
  FROM vehicles WHERE slug IN ('ng-rb-122-police-interceptor', 'ng-122-exo-police-power-armor', 'ng-hch-1228-hovertrain-locomotive', 'ng-hcb-1b-hovertrain-boxcar', 'ng-hcb-ad2-hovertrain-weapon-car');
SELECT 'their 36 locations are in' AS assertion, count(*) AS got, 36 AS want
  FROM vehicle_locations WHERE vehicle_slug IN ('ng-rb-122-police-interceptor', 'ng-122-exo-police-power-armor', 'ng-hch-1228-hovertrain-locomotive', 'ng-hcb-1b-hovertrain-boxcar', 'ng-hcb-ad2-hovertrain-weapon-car');
SELECT 'their 16 weapon entries are in' AS assertion, count(*) AS got, 16 AS want
  FROM vehicle_weapons WHERE vehicle_slug IN ('ng-rb-122-police-interceptor', 'ng-122-exo-police-power-armor', 'ng-hch-1228-hovertrain-locomotive', 'ng-hcb-1b-hovertrain-boxcar', 'ng-hcb-ad2-hovertrain-weapon-car');
SELECT 'each main body location equals mdc_main_body' AS assertion, count(*) AS got, 0 AS want
  FROM vehicles v JOIN vehicle_locations l ON l.vehicle_slug = v.slug AND l.location = 'Main Body'
  WHERE v.slug IN ('ng-rb-122-police-interceptor', 'ng-122-exo-police-power-armor', 'ng-hch-1228-hovertrain-locomotive', 'ng-hcb-1b-hovertrain-boxcar', 'ng-hcb-ad2-hovertrain-weapon-car') AND l.mdc IS NOT NULL AND v.mdc_main_body IS NOT NULL AND l.mdc <> v.mdc_main_body;

-- Records this run. See db/migrations/024-data-script-runs.sql.
INSERT INTO data_script_runs (filename) VALUES ('~292-northern-gun-1-vehicles-police-hovertrain.sql');
